<?= view('store/partials/size_filter', ['sizeId'=>'admin-product-size','sizeValue'=>$filters['size'] ?? '', 'sizes'=>$sizes ?? [], 'adminSize'=>true]) ?>
<select name="status" aria-label="وضعیت محصول" data-admin-filter><?php foreach ([''=>'همه وضعیت‌ها','active'=>'منتشر شده','draft'=>'پیش‌نویس','archived'=>'بایگانی'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($filters['status']??'')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select>
<select name="category_id" aria-label="دسته‌بندی" data-admin-filter><option value="">همه دسته‌ها</option><?php foreach ($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= (string)($filters['category_id']??'')===(string)$category['id']?'selected':'' ?>><?= esc($category['name']) ?></option><?php endforeach; ?></select>
<select name="brand_id" aria-label="برند" data-admin-filter><option value="">همه برندها</option><?php foreach ($brands as $brand): ?><option value="<?= (int)$brand['id'] ?>" <?= (string)($filters['brand_id']??'')===(string)$brand['id']?'selected':'' ?>><?= esc($brand['name']) ?></option><?php endforeach; ?></select>
<button type="submit" class="admin-button admin-button-soft">جست‌وجو</button><a class="admin-button" href="<?= site_url('admin/products/create') ?>">+ افزودن محصول</a>
</form>
<section class="admin-panel"><div class="admin-panel-heading"><h2>همه محصولات</h2><span class="admin-muted"><?= admin_number((int)$pagination['total']) ?> محصول</span></div>
