<?php foreach ($products as $product): ?><tr><td><div class="admin-product-cell"><?php if (!empty($product['image_path'])): ?><img src="<?= esc(base_url(ltrim($product['image_path'],'/')), 'attr') ?>" alt="" width="44" height="44"><?php else: ?><span class="admin-product-placeholder"><img src="<?= base_url('assets/figma/admin/7bc70.svg') ?>" alt="" width="20" height="20"></span><?php endif; ?><div><?= esc($product['name']) ?><div class="admin-muted">#<?= (int)$product['id'] ?></div></div></div></td><td><?= esc($product['brand_name']??'—') ?></td><td><?php if((int)($product['compare_at_price_toman']??0)>(int)$product['price_toman']): ?><del class="admin-muted"><?= admin_number((int)$product['compare_at_price_toman']) ?></del><br><?php endif; ?><strong><?= admin_number((int)$product['price_toman']) ?></strong></td><td><?= admin_number((int)$product['stock']) ?> جفت</td><td><span title="بازدید ثبت‌شده؛ تکرار در همان نشست تا ۳۰ دقیقه شمرده نمی‌شود"><?= isset($product['product_views'])?admin_number((int)$product['product_views']):'—' ?> بازدید</span><br><a href="<?= site_url('admin/comments?status=&product_id='.(int)$product['id']) ?>"><?= isset($product['comment_count'])?admin_number((int)$product['comment_count']):'—' ?> دیدگاه</a></td><td><form method="post" action="<?= site_url('admin/products/'.(int)$product['id'].'/status') ?>" class="admin-stock-form"><?= csrf_field() ?><select name="status" aria-label="وضعیت انتشار <?= esc($product['name'],'attr') ?>"><?php foreach(['active'=>'منتشر شده','draft'=>'پیش‌نویس','archived'=>'بایگانی'] as $value=>$label): ?><option value="<?= $value ?>" <?= $product['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button type="submit">ثبت</button></form></td><td><a href="<?= site_url('admin/products/'.(int)$product['id'].'/edit') ?>">ویرایش</a></td></tr><?php endforeach; ?>
